using System;

public class IWaiterTests
{
[Theory]
[InlineData(0)]
[InlineData(1)]
[InlineData(100)]
[InlineData(1000)]
public async Task Delay_ShouldRespectProvidedTimeSpan(int milliseconds)
{
    // Arrange
    var waiter = new Waiter();
    var delay = TimeSpan.FromMilliseconds(milliseconds);
    var cts = new CancellationTokenSource();

    // Act
    var startTime = DateTime.UtcNow;
    await waiter.Delay(delay, cts.Token);
    var endTime = DateTime.UtcNow;

    // Assert
    var actualDelay = endTime - startTime;
    Assert.True(actualDelay >= delay, $"Actual delay ({actualDelay}) should be greater than or equal to requested delay ({delay})");
    Assert.True(actualDelay < delay.Add(TimeSpan.FromSeconds(1)), $"Actual delay ({actualDelay}) should be less than requested delay plus 1 second tolerance ({delay.Add(TimeSpan.FromSeconds(1))})");

[Fact]
public async Task Delay_WithCancellationTokenNone_CompletesWithoutCancellation()
{
    // Arrange
    IWaiter waiter = new Waiter();
    TimeSpan delay = TimeSpan.FromMilliseconds(50);
    
    // Act & Assert
    await Assert.DoesNotThrowAsync(async () =>
    {
