    });

[Theory]
[InlineData(0)]
[InlineData(100)]
[InlineData(1000)]
[InlineData(5000)]
public async Task Delay_WaitsForSpecifiedTime(int milliseconds)
{
    // Arrange
    var waiter = new Waiter();
    var delay = TimeSpan.FromMilliseconds(milliseconds);
    var cts = new CancellationTokenSource();
    var stopwatch = new System.Diagnostics.Stopwatch();

    // Act
    stopwatch.Start();
    await waiter.Delay(delay, cts.Token);
    stopwatch.Stop();

    // Assert
    var actualDelay = stopwatch.Elapsed;
    Assert.True(actualDelay >= delay, $"Actual delay ({actualDelay}) should be greater than or equal to requested delay ({delay})");
    Assert.True(actualDelay < delay.Add(TimeSpan.FromSeconds(1)), $"Actual delay ({actualDelay}) should not exceed requested delay ({delay}) by more than 1 second");

[Fact]
public async Task Delay_WithCancellation_ShouldThrowOperationCanceledException()
{
    // Arrange
    var waiter = new Waiter();
    var cts = new CancellationTokenSource();
    var delay = TimeSpan.FromSeconds(5);

    // Act & Assert
    cts.Cancel(); // Cancel immediately
    await Assert.ThrowsAsync<OperationCanceledException>(() => 
        waiter.Delay(delay, cts.Token));
}
